/*
 * prog24_query_string_parser
 *
 * The original binary reads a line from *stdin*, removes a trailing '\n'
 * (and an optional '\r'), then parses the line as an HTTP‑style query
 * string:  key1=value1&key2=value2&...
 *
 * Each key and value is URL‑decoded ( '+' → space, %XX → byte ) and
 * printed on its own line in the form:
 *
 *      key=value
 *
 * If the input line is empty (fgets returns NULL) the program prints
 * the literal string "NO_INPUT".  At most 64 key/value pairs are
 * processed – the original program stopped parsing after the 64th
 * pair.
 *
 * The behaviour reproduced below matches the observable output of the
 * original (obfuscated) binary.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE   0x800          /* 2048 bytes – same as the original buffer */
#define MAX_PAIRS  64

static char main_line[MAX_LINE];
static char main_key[MAX_LINE];
static char main_val[MAX_LINE];

/* -------------------------------------------------------------
 * URL‑decode a fragment.
 *
 *  src   – pointer to the fragment to decode
 *  len   – length of the fragment (may be zero)
 *  dst   – buffer where the decoded string is stored; it will be
 *          NUL‑terminated.
 *
 * The implementation follows the logic of the original `decode`
 * function: '+' becomes a space, '%' followed by two hex digits is
 * converted to the corresponding byte, otherwise the character is
 * copied unchanged.
 * ------------------------------------------------------------- */
static void decode(const char *src, size_t len, char *dst)
{
    size_t i = 0;          /* index in src */
    size_t o = 0;          /* index in dst */

    while (i < len) {
        char c = src[i];

        if (c == '+') {
            dst[o++] = ' ';
            ++i;
        } else if (c == '%' && i + 2 < len &&
                   isxdigit((unsigned char)src[i+1]) &&
                   isxdigit((unsigned char)src[i+2])) {
            /* convert two hex digits */
            char hi = src[i+1];
            char lo = src[i+2];
            int vhi = (hi >= '0' && hi <= '9') ? hi - '0' :
                      (hi >= 'a' && hi <= 'f') ? hi - 'a' + 10 :
                      hi - 'A' + 10;
            int vlo = (lo >= '0' && lo <= '9') ? lo - '0' :
                      (lo >= 'a' && lo <= 'f') ? lo - 'a' + 10 :
                      lo - 'A' + 10;
            dst[o++] = (char)((vhi << 4) | vlo);
            i += 3;          /* skip %XX */
        } else {
            dst[o++] = c;
            ++i;
        }
    }
    dst[o] = '\0';
}

/* -------------------------------------------------------------
 * Main program – reproduces the original state‑machine logic in a
 * straightforward way.
 * ------------------------------------------------------------- */
int main(void)
{
    char *p = fgets(main_line, sizeof(main_line), stdin);
    if (p == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* Trim trailing newline and optional carriage‑return */
    size_t len = strlen(main_line);
    while (len > 0 && (main_line[len-1] == '\n' || main_line[len-1] == '\r')) {
        main_line[--len] = '\0';
    }

    size_t pos = 0;          /* current scanning position */
    int    pair_cnt = 0;     /* number of printed pairs */

    while (pos < len && pair_cnt < MAX_PAIRS) {
        size_t key_start = pos;
        size_t key_len   = 0;
        size_t val_start = 0;
        size_t val_len   = 0;
        int    have_value = 0;

        /* Scan until '=' or '&' or end of line */
        while (pos < len && main_line[pos] != '=' && main_line[pos] != '&')
            ++pos;

        if (pos < len && main_line[pos] == '=') {
            /* We have a key=value pair */
            key_len = pos - key_start;
            ++pos;                     /* skip '=' */
            val_start = pos;
            while (pos < len && main_line[pos] != '&')
                ++pos;
            val_len = pos - val_start;
            have_value = 1;
        } else {
            /* No '=', the whole token is a key with empty value */
            key_len = pos - key_start;
            have_value = 0;
        }

        /* Decode key */
        decode(main_line + key_start, key_len, main_key);

        /* Decode value (if any) */
        if (have_value && val_len > 0) {
            decode(main_line + val_start, val_len, main_val);
        } else {
            main_val[0] = '\0';
        }

        /* Output the pair */
        printf("%s=%s\n", main_key, main_val);
        ++pair_cnt;

        /* Skip the '&' separator, if present */
        if (pos < len && main_line[pos] == '&')
            ++pos;
    }

    return 0;
}
